 'indexes',(select jsonb_agg(jsonb_build_array(i.relname,x.indisvalid,x.indisready,x.indislive,pg_get_indexdef(i.oid)) order by i.relname) from pg_index x join pg_class i on i.oid=x.indexrelid where x.indrelid=c.oid),
 'triggers',(select jsonb_agg(jsonb_build_array(tr.tgname,tr.tgenabled,pg_get_triggerdef(tr.oid)) order by tr.tgname) from pg_trigger tr where tr.tgrelid=c.oid and not tr.tgisinternal),
